code.java:
class Solution {
    public int pivotInteger(int n){
        int total=n*(n+1)/2;
        int root=(int)Math.sqrt(total);
        return root*root==total?root:-1;
    }
}

code.kotlin:
class Solution {
    fun pivotInteger(n:Int):Int{
        val total=n*(n+1)/2;
        val root=kotlin.math.sqrt(total.toDouble()).toInt();
        return if(root*root==total)root else -1
    }
}

